<body>
  <div id="root"></div>

  <script>
    const root = document.getElementById('root');

    const state = {
      dialogOpen: false,
      lastActiveElement: null,
      imageDeleted: false
    };

    function h(tag, attrs = {}, ...children) {
      const el = document.createElement(tag);
      for (const [key, value] of Object.entries(attrs)) {
        if (key === 'className') el.className = value;
        else if (key === 'textContent') el.textContent = value;
        else if (key === 'dataset') Object.assign(el.dataset, value);
        else if (key.startsWith('on') && typeof value === 'function') {
          el.addEventListener(key.slice(2).toLowerCase(), value);
        } else if (value !== false && value != null) {
          el.setAttribute(key, value);
        }
      }
      for (const child of children.flat()) {
        if (child == null) continue;
        el.append(child.nodeType ? child : document.createTextNode(child));
      }
      return el;
    }

    function openDialog() {
      state.lastActiveElement = document.activeElement;
      state.dialogOpen = true;
      render();
      requestAnimationFrame(() => {
        const focusTarget = document.querySelector('[data-dialog-cancel]');
        if (focusTarget) focusTarget.focus();
      });
    }

    function closeDialog() {
      state.dialogOpen = false;
      render();
      const trigger = document.querySelector('.trigger');
      if (trigger) trigger.focus();
    }

    function confirmDelete() {
      state.imageDeleted = true;
      state.dialogOpen = false;
      render();
      const trigger = document.querySelector('.trigger');
      if (trigger) trigger.focus();
    }

    function ImagePreviewPage() {
      const wrapper = h('main', { className: 'app', 'aria-label': 'Image preview page' });
      const card = h('section', { className: 'card preview' });

      const image = h('div', { className: 'image-frame' },
        h('img', {
          src: 'https://images.unsplash.com/photo-1519608487953-e999c86e7455?auto=format&fit=crop&w=1400&q=80',
          alt: 'A scenic mountain landscape reflected in a calm lake'
        })
      );

      const copy = h('div', {},
        h('h1', { textContent: 'Mountain Lake' }),
        h('p', { className: 'meta', textContent: 'Saved in your image library' })
      );

      const actions = h('div', { className: 'actions' },
        h('button', {
          type: 'button',
          className: 'button trigger',
          onClick: openDialog,
          'aria-haspopup': 'dialog',
          'aria-controls': 'delete-dialog',
          textContent: 'Delete image'
        })
      );

      const details = h('div', { className: 'details' }, copy, actions);
      const status = h('div', { className: 'status', id: 'status', role: 'status', 'aria-live': 'polite' },
        state.imageDeleted ? 'Image deleted from your library.' : ''
      );

      card.append(image, details, status);
      wrapper.append(card);

      if (state.dialogOpen) {
        wrapper.append(DeleteConfirmDialog());
      }

      return wrapper;
    }

    function DeleteConfirmDialog() {
      const backdrop = h('div', {
        className: 'dialog-backdrop',
        role: 'presentation',
        onClick: (event) => {
          if (event.target === backdrop) closeDialog();
        }
      });

      const panel = h('section', {
        id: 'delete-dialog',
        className: 'dialog-panel',
        role: 'dialog',
        'aria-modal': 'true',
        'aria-labelledby': 'delete-dialog-title',
        'aria-describedby': 'delete-dialog-description',
        onKeydown: (event) => {
          if (event.key !== 'Tab') return;
          const focusable = panel.querySelectorAll('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])');
          const items = Array.from(focusable).filter((item) => !item.hasAttribute('disabled'));
          if (!items.length) return;
          const first = items[0];
          const last = items[items.length - 1];
          if (event.shiftKey && document.activeElement === first) {
            event.preventDefault();
            last.focus();
          } else if (!event.shiftKey && document.activeElement === last) {
            event.preventDefault();
            first.focus();
          }
        }
      });

      const closeButton = h('button', {
        type: 'button',
        className: 'button secondary',
        onClick: closeDialog,
        'data-dialog-cancel': 'true',
        textContent: 'Cancel'
      });

      const deleteButton = h('button', {
        type: 'button',
        className: 'button danger',
        onClick: confirmDelete,
        textContent: 'Delete'
      });

      panel.append(
        h('h2', { className: 'dialog-title', id: 'delete-dialog-title', textContent: 'Delete this image?' }),
        h('p', {
          className: 'dialog-copy',
          id: 'delete-dialog-description',
          textContent: "This will remove the image from your library. You can't undo this action."
        }),
        h('div', { className: 'dialog-actions' }, closeButton, deleteButton)
      );

      backdrop.append(panel);
      return backdrop;
    }

    function render() {
      root.replaceChildren(ImagePreviewPage());
      document.body.style.overflow = state.dialogOpen ? 'hidden' : '';
    }

    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape' && state.dialogOpen) {
        closeDialog();
      }
    });

    render();
  </script>
</body>
